#include <iostream>
using namespace std;

const int V = 5;
int parent[V];

int find(int x) {
    while (parent[x] != x) {
        x = parent[x];
    }
    return x;
}

int main() {
    int graph[V][V] = {
        {0, 4, 1, 0, 0},
        {4, 0, 2, 5, 0},
        {1, 2, 0, 8, 0},
        {0, 5, 8, 0, 3},
        {0, 0, 0, 3, 0},
    };
    int eu[10];
    int ev[10];
    int ew[10];
    int e = 0;
    for (int u = 0; u < V; u++) {
        for (int v = u + 1; v < V; v++) {
            if (graph[u][v] > 0) {
                eu[e] = u;
                ev[e] = v;
                ew[e] = graph[u][v];
                e++;
            }
        }
    }
    for (int i = 0; i < e - 1; i++) {
        for (int j = 0; j < e - i - 1; j++) {
            if (ew[j] > ew[j + 1]) {
                swap(ew[j], ew[j + 1]);
                swap(eu[j], eu[j + 1]);
                swap(ev[j], ev[j + 1]);
            }
        }
    }
    for (int i = 0; i < V; i++) {
        parent[i] = i;
    }
    int total = 0;
    for (int k = 0; k < e; k++) {
        int a = find(eu[k]);
        int b = find(ev[k]);
        if (a != b) {
            parent[a] = b;
            total += ew[k];
            cout << eu[k] << " - " << ev[k] << endl;
        }
    }
    cout << "Total weight " << total << endl;
    return 0;
}
